import base64
import os

# 1 second of MP3 silence from reliable Gist
mp3_base64 = ""

path = r"D:\Projects\hvylyna movchannya\hvylyna-movchannya\public\audio\silence.mp3"
os.makedirs(os.path.dirname(path), exist_ok=True)
with open(path, "wb") as f:
    f.write(base64.b64decode(mp3_base64))
print(f"Created {path}, size: {os.path.getsize(path)} bytes")
